const platforms=['Netflix','Prime Video','Sun NXT','JioHotstar','ZEE5','aha','SonyLIV'];
const languages=['English','Hindi','Telugu','Tamil','Kannada','Malayalam'];
const titles=[
['The Last Horizon','Movie',2026,'Netflix',['English','Hindi'],'#456359',true],
['Hyderabad Nights','Series',2026,'aha',['Telugu','Tamil'],'#70483a',true],
['Monsoon Letters','Movie',2025,'Prime Video',['Malayalam','Tamil','Hindi'],'#46647b',false],
['City of Echoes','Series',2026,'SonyLIV',['Hindi','English'],'#675173',true],
['A Sunday in Chennai','Movie',2026,'Sun NXT',['Tamil','Telugu'],'#9b6740',false],
['Beyond the Hills','Movie',2026,'ZEE5',['Kannada','Telugu'],'#536744',true],
['The Quiet Coast','Series',2025,'JioHotstar',['English','Hindi','Tamil'],'#376c72',false],
['Homeward Bound','Movie',2026,'Prime Video',['Malayalam','Kannada'],'#866252',true]
].map((x,id)=>({id,title:x[0],type:x[1],year:x[2],platform:x[3],audio:x[4],color:x[5],weekly:x[6]}));
let saved;try{saved=new Set(JSON.parse(localStorage.getItem('ottscout-watchlist')||'[]'))}catch{saved=new Set()}
let selectedPlatforms=new Set(platforms),selectedLanguages=new Set(languages),view='discover';
const $=s=>document.querySelector(s);
function chips(list,selected,container){$(container).replaceChildren(...list.map(name=>{const b=document.createElement('button');b.textContent=name;b.setAttribute('aria-pressed',selected.has(name));b.onclick=()=>{selected.has(name)?selected.delete(name):selected.add(name);chips(list,selected,container);render()};return b}))}
function render(){const query=$('#search').value.toLowerCase().trim(),type=$('#type').value;const found=titles.filter(t=>selectedPlatforms.has(t.platform)&&t.audio.some(l=>selectedLanguages.has(l))&&t.title.toLowerCase().includes(query)&&(type==='all'||t.type===type)&&(view!=='watchlist'||saved.has(t.id))&&(view!=='weekly'||t.weekly));$('#count').textContent=saved.size;$('#heading').textContent={discover:'A little something for every mood',weekly:'Fresh picks for your week',watchlist:'Your next movie night starts here'}[view];$('#description').textContent=view==='weekly'?'Illustrative weekly selection — live release dates are not connected.':view==='watchlist'?'Saved on this browser. Alerts are not connected yet.':'Explore the sample catalog. Save a title for later.';$('#catalog').replaceChildren(...found.map(t=>{const card=document.createElement('article');card.className='card';card.innerHTML=`<div class="poster" style="--c:${t.color}"><span class="badge">${t.type} · SAMPLE</span><strong>${t.title}</strong><button class="save" aria-label="${saved.has(t.id)?'Remove from':'Add to'} watchlist: ${t.title}" aria-pressed="${saved.has(t.id)}">${saved.has(t.id)?'✓':'+'}</button></div><div class="details"><h3>${t.title}</h3><div class="meta">${t.year} · ${t.type} · Illustrative title</div><div class="provider">${t.platform} · Sample listing</div><div class="audio">Audio: ${t.audio.join(' · ')}<br>Subtitles: Unverified</div></div>`;card.querySelector('button').onclick=()=>{saved.has(t.id)?saved.delete(t.id):saved.add(t.id);try{localStorage.setItem('ottscout-watchlist',JSON.stringify([...saved]))}catch{}render()};return card}));if(!found.length){const empty=document.createElement('div');empty.className='empty';empty.textContent=view==='watchlist'?'No saved titles match your filters. Save a title from Discover or adjust your filters.':'No titles match. Try another search or select more platforms and languages.';$('#catalog').append(empty)}}
chips(platforms,selectedPlatforms,'#platforms');chips(languages,selectedLanguages,'#languages');$('#search').oninput=render;$('#type').onchange=render;$('#all').onclick=()=>{selectedPlatforms.clear();platforms.forEach(p=>selectedPlatforms.add(p));chips(platforms,selectedPlatforms,'#platforms');render()};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('nav button').forEach(n=>n.classList.toggle('active',n===b));render()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#search').focus()}});render();
